type logJoins[Q dialect.Joinable] struct {
	typ        string
	GameServer modAs[Q, gameServerColumns]
	Game       modAs[Q, gameColumns]
	User       modAs[Q, userColumns]
}

func (j logJoins[Q]) aliasedAs(alias string) logJoins[Q] {
	return buildLogJoins[Q](buildLogColumns(alias), j.typ)
}

func buildLogJoins[Q dialect.Joinable](cols logColumns, typ string) logJoins[Q] {
	return logJoins[Q]{
		typ: typ,
		GameServer: modAs[Q, gameServerColumns]{
			c: GameServers.Columns,
			f: func(to gameServerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, GameServers.Name().As(to.Alias())).On(
						to.ID.EQ(cols.GameServerID),
					))
				}

				return mods
			},
		},
		Game: modAs[Q, gameColumns]{
			c: Games.Columns,
			f: func(to gameColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Games.Name().As(to.Alias())).On(
						to.ID.EQ(cols.GameID),
					))
				}

				return mods
			},
		},
		User: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.Name().As(to.Alias())).On(
						to.ID.EQ(cols.UserID),
					))
				}

				return mods
			},
		},
	}
}
